+    public static BeanFactoryPostProcessor deferUnwiredControllers() {
         return factory -> {
-            if (factory.containsBeanDefinition("windowBroadcastController") && factory.getBeanNamesForType(BroadcastService.class, true, false).length == 0) {
-                factory.getBeanDefinition("windowBroadcastController").setLazyInit(true);
